const form = $('SUG Receipt Form').first().json;
const student = $('Find Student').first().json;
const fee = $('Find Fee').first().json;
const rows = $input.all().map(i => i.json).filter(r => r['Receipt No']);
const OFFICE = 'sylvesterchidera+008@gmail.com';

const matric = String(form['Matric Number'] || '').trim();
const paymentFor = String(form['Payment For'] || 'SUG Dues').trim();

const bad = r => [{ json: { ok: false, reason: r, officeEmail: OFFICE, matric, paymentFor } }];

// Pulls from the flat fee column ('Fee') in your Google Sheet
const amount = Number(fee['Fee'] || fee['Amount']);
if (!amount) return bad('No SUG fee is set in the Fees tab.');

// Optional: Checks if this student already paid for this specific purpose
const dup = rows.find(r => 
  String(r['Matric No']).trim() === matric && 
  String(r['Purpose'] || r['Payment For'] || '').trim() === paymentFor
);
if (dup) return bad(`Already paid: receipt ${dup['Receipt No']} already exists for ${matric} (${paymentFor}). Use the re-resend form if the student lost it.`);

let max = 0;
for (const r of rows) {
  const m = String(r['Receipt No']).match(/(\d+)$/);
  if (m) max = Math.max(max, parseInt(m[1], 10));
}

const receiptNo = 'SUG-' + String(max + 1).padStart(6, '0');
const dateText = new Date().toLocaleDateString('en-GB', { timeZone: 'Africa/Lagos' });

const email = String(student['Email'] || '').trim();
const valid = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email);

return [{
  json: {
    ok: true,
    isResend: false,
    receiptNo,
    fileName: receiptNo + '.pdf',
    dateText,
    name: student['Name'],
    matric,
    level: student['Level'],
    paymentFor,
    purposeText: paymentFor,
    amount,
    duplicateNote: '',
    to: email,
    emailStatus: valid ? 'SENT' : 'INVALID EMAIL',
    emailValid: valid,
    officeEmail: OFFICE
  }
}];

