function jpegInfo(b64, name){
  const buf = Buffer.from(b64, 'base64');
  let i = 2;
  while(i + 8 < buf.length){
    if(buf[i] !== 0xFF){ i++; continue; }
    const m = buf[i+1];
    if(m >= 0xC0 && m <= 0xCF && m !== 0xC4 && m !== 0xC8 && m !== 0xCC) return { buf, h: buf.readUInt16BE(i+5), w: buf.readUInt16BE(i+7) };
    i += 2 + buf.readUInt16BE(i+2);
  }
  throw new Error('Bad image: ' + name);
